INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2850520, 398266, 30049, '<td valign="top">Hi Chris.  Bummer about the score on your Geometry entry: <a href="//www.dpchallenge.com/image.php?IMAGE_ID=395045" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_challenge/554/thumb/395045.jpg'', strrpos(''//images.dpchallenge.com/images_challenge/554/thumb/395045.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_challenge/554/thumb/395045.jpg"/></a>.  Yes, I looked it up from the screenshot in this ''Electricity'' entry.<br/> <br/>You''ve certainly met the challenge theme with this as illustrated by the various electronics evident in your image.  The use of B/W was a good choice.  <br/> <br/>Will be interesting to see what other feedback you get about the screenshot.  ;^)  Good luck in the challenge.</td>', 'Hi Chris.  Bummer about the score on your Geometry entry: .  Yes, I looked it up from the screenshot in this ''Electricity'' entry. You''ve certainly met the challenge theme with this as illustrated by the various electronics evident in your image.  The use of B/W was a good choice.   Will be interesting to see what other feedback you get about the screenshot.  ;^)  Good luck in the challenge.', '2006-09-20 10:49:51.000000', NULL, 1),
(2850523, 398627, 65894, '<td valign="top">Beautiful and effective. I would love to now how you dont that. Different from other photos and works well.</td>', 'Beautiful and effective. I would love to now how you dont that. Different from other photos and works well.', '2006-09-20 10:50:30.000000', NULL, 1),
(2850537, 398381, 30049, '<td valign="top">This is a fun image and shows good use of electricity and it''s impact on society (how else can she dry her hair?).  Composition works well, and the image is well focused and sharp.  My only complaint is the color tone - looks kind of purplish.  Good luck in the challenge.</td>', 'This is a fun image and shows good use of electricity and it''s impact on society (how else can she dry her hair?).  Composition works well, and the image is well focused and sharp.  My only complaint is the color tone - looks kind of purplish.  Good luck in the challenge.', '2006-09-20 10:57:27.000000', NULL, 1),
(2850627, 397217, 57320, '<td valign="top">Good idea, not so good exicution. The foucus should be very sharp for a photo like this one</td>', 'Good idea, not so good exicution. The foucus should be very sharp for a photo like this one', '2006-09-20 11:26:48.000000', NULL, 1),
