(2851460, 398378, 65498, '<td valign="top">nice photo.. great perspective</td>', 'nice photo.. great perspective', '2006-09-20 15:38:53.000000', NULL, 1),
(2851534, 398071, 65858, '<td valign="top">Interesting shot.  I like the silouhette effect and the uncommon blue background thereof.    I think it would help if the lines were a little sharper.</td>', 'Interesting shot.  I like the silouhette effect and the uncommon blue background thereof.    I think it would help if the lines were a little sharper.', '2006-09-20 16:08:04.000000', NULL, 1),
(2851537, 398618, 65858, '<td valign="top">I like the human element of this photo.  It''d be nice if there was a little more detail in her face.</td>', 'I like the human element of this photo.  It''d be nice if there was a little more detail in her face.', '2006-09-20 16:09:25.000000', NULL, 1),
(2851540, 396086, 65858, '<td valign="top">An interesting idea.  I think the flecks on your windshield and dashboard are a little distracting.</td>', 'An interesting idea.  I think the flecks on your windshield and dashboard are a little distracting.', '2006-09-20 16:10:43.000000', NULL, 1),
(2851543, 398457, 65858, '<td valign="top">Cool shot.  I would have liked to see the fountains up closer, but then you might have lost the globe effect, so it''s a tough call.</td>', 'Cool shot.  I would have liked to see the fountains up closer, but then you might have lost the globe effect, so it''s a tough call.', '2006-09-20 16:12:37.000000', NULL, 1),
(2851544, 398057, 65858, '<td valign="top">Wow, fascinating shot.  I hope your comment explains how it was done!  =)</td>', 'Wow, fascinating shot.  I hope your comment explains how it was done!  =)', '2006-09-20 16:13:51.000000', NULL, 1),
(2851548, 396835, 65858, '<td valign="top">Interesting shot.  The powerlines seem a little busy, but perhaps a good portrayal of them.</td>', 'Interesting shot.  The powerlines seem a little busy, but perhaps a good portrayal of them.', '2006-09-20 16:14:57.000000', NULL, 1),
(2851550, 397501, 65858, '<td valign="top">Clever title.  The dark setting and lighting on the hand make it all the more mystical.</td>', 'Clever title.  The dark setting and lighting on the hand make it all the more mystical.', '2006-09-20 16:16:12.000000', NULL, 1),
(2851555, 398332, 65858, '<td valign="top">I find myself slightly distracted as to what''s the subject of this photo.</td>', 'I find myself slightly distracted as to what''s the subject of this photo.', '2006-09-20 16:17:26.000000', NULL, 1),
(2851557, 395966, 65858, '<td valign="top">The glow is interesting, but I''d like to see more context.</td>', 'The glow is interesting, but I''d like to see more context.', '2006-09-20 16:18:25.000000', NULL, 1),
(2851574, 398554, 65858, '<td valign="top">Fits the theme well.  Somehow it seems like it could have been framed better.  I like the green glow of the train.</td>', 'Fits the theme well.  Somehow it seems like it could have been framed better.  I like the green glow of the train.', '2006-09-20 16:22:00.000000', NULL, 1),
(2851580, 397813, 65858, '<td valign="top">Nice.  The title definitely adds to the understanding that it is supposed to look very busy.  The background sky is very nice.</td>', 'Nice.  The title definitely adds to the understanding that it is supposed to look very busy.  The background sky is very nice.', '2006-09-20 16:22:57.000000', NULL, 1),
(2851584, 398460, 65858, '<td valign="top">Nice sharp lines.  Compelling title.  Very nice.</td>', 'Nice sharp lines.  Compelling title.  Very nice.', '2006-09-20 16:23:58.000000', NULL, 1),
(2851588, 397804, 65858, '<td valign="top">In such a shot, I might like to see both subjects in focus.</td>', 'In such a shot, I might like to see both subjects in focus.', '2006-09-20 16:24:47.000000', NULL, 1),
(2851594, 396996, 65858, '<td valign="top">Interesting idea.  The cool part is that you can get electricity from some fruits.  =)  The cantelope looks a bit out of focus.</td>', 'Interesting idea.  The cool part is that you can get electricity from some fruits.  =)  The cantelope looks a bit out of focus.', '2006-09-20 16:26:44.000000', NULL, 1),
(2851603, 395581, 65858, '<td valign="top">Technically it''s a nice sharp shot.  The subject doesn''t scream "electricity" to me though...</td>', 'Technically it''s a nice sharp shot.  The subject doesn''t scream "electricity" to me though...', '2006-09-20 16:28:33.000000', NULL, 1),
(2851605, 398627, 65858, '<td valign="top">A little cliche, but a good subject nonetheless.  The focus looks a little soft - I won''t knock on being able to see the wire due to the basic editing.  =)</td>', 'A little cliche, but a good subject nonetheless.  The focus looks a little soft - I won''t knock on being able to see the wire due to the basic editing.  =)', '2006-09-20 16:29:36.000000', NULL, 1),
(2851613, 398434, 65858, '<td valign="top">Nice original twist on the theme!  I might have liked more color variance, though the monotone may have been intentional.</td>', 'Nice original twist on the theme!  I might have liked more color variance, though the monotone may have been intentional.', '2006-09-20 16:32:09.000000', NULL, 1),
(2851623, 398139, 65858, '<td valign="top">I like the irony of how this shot, while capturing a lot of light, conveys a dark or empty feeling.  The person seems a little underexposed, but it''s understandable given the lights.</td>', 'I like the irony of how this shot, while capturing a lot of light, conveys a dark or empty feeling.  The person seems a little underexposed, but it''s understandable given the lights.', '2006-09-20 16:34:47.000000', NULL, 1),
(2851626, 398025, 65858, '<td valign="top">=)  While the subject seems a bit mundane, I like the humor!</td>', '=)  While the subject seems a bit mundane, I like the humor!', '2006-09-20 16:35:44.000000', NULL, 1),
(2851630, 398304, 65858, '<td valign="top">Interesting idea.  Good work on the title - otherwise it''s just a picture of half a cellphone.  =)</td>', 'Interesting idea.  Good work on the title - otherwise it''s just a picture of half a cellphone.  =)', '2006-09-20 16:36:58.000000', NULL, 1),
(2851635, 396724, 65858, '<td valign="top">Nice human element.  Interestingly, this is not the only fan shot.  I think if it was a little sharper, it''d be very powerful.</td>', 'Nice human element.  Interestingly, this is not the only fan shot.  I think if it was a little sharper, it''d be very powerful.', '2006-09-20 16:38:48.000000', NULL, 1),
(2851637, 397285, 60701, '<td valign="top">I like the lines across the image but I would like to see the lighting on the right side of the supports.  They look very dark right now.</td>', 'I like the lines across the image but I would like to see the lighting on the right side of the supports.  They look very dark right now.', '2006-09-20 16:39:26.000000', NULL, 1),
(2851641, 398440, 65858, '<td valign="top">I like the stop-action quality of this shot and the vivid colors!  Very nice!  It seems like there just a bit of fuzziness on his shirt and facemask.</td>', 'I like the stop-action quality of this shot and the vivid colors!  Very nice!  It seems like there just a bit of fuzziness on his shirt and facemask.', '2006-09-20 16:40:18.000000', NULL, 1),
(2851646, 398057, 30049, '<td valign="top">Clever piece of painting with light!  Fun composition and nice overall tone to this.  Good luck in the challenge.</td>', 'Clever piece of painting with light!  Fun composition and nice overall tone to this.  Good luck in the challenge.', '2006-09-20 16:41:02.000000', NULL, 1),
(2851663, 397501, 48389, '<td valign="top">I was expecting to see a lot more shots along these lines but seems you picked a good subject!! Just enough light and detail on the hand so as not to distract from the beautiful blue line. I love the purple tint to the edge of the ball too, great work :o)</td>', 'I was expecting to see a lot more shots along these lines but seems you picked a good subject!! Just enough light and detail on the hand so as not to distract from the beautiful blue line. I love the purple tint to the edge of the ball too, great work :o)', '2006-09-20 16:48:39.000000', NULL, 1),
(2851719, 397810, 29156, '<td valign="top">very beautiful, great light and colors</td>', 'very beautiful, great light and colors', '2006-09-20 17:19:44.000000', NULL, 1),
(2851722, 396387, 6999, '<td valign="top">This has a certain something to it - though your crop pretty quickly begins to seem rather arbitrary. The toning is well done, but your subject, as is apparent from your depth of field, doesn''t quite tie in with your title from where I''m sitting.</td>', 'This has a certain something to it - though your crop pretty quickly begins to seem rather arbitrary. The toning is well done, but your subject, as is apparent from your depth of field, doesn''t quite tie in with your title from where I''m sitting.', '2006-09-20 17:21:29.000000', NULL, 1),
(2851734, 398012, 6999, '<td valign="top">Marvellous stuff. I don''t find lighting shots particularly interesting personally, but can appreciate that this is as good as they get - or almost so.  Maintaining some interest in the clouds and water shows careful exposure, and a thoughtful approach. Just one thought: presuming that this is one of a number of shots (after all, you don''t just turn up and take one in this situation, do you?), I wonder if you haven''t taken the one with the most lightning in it as the best - was there something a touch simpler, and perhaps the more impactful for it? The sheer quantity here makes it perhaps less dramatic than a more coherent, simpler structure of lines might be.</td>', 'Marvellous stuff. I don''t find lighting shots particularly interesting personally, but can appreciate that this is as good as they get - or almost so.  Maintaining some interest in the clouds and water shows careful exposure, and a thoughtful approach. Just one thought: presuming that this is one of a number of shots (after all, you don''t just turn up and take one in this situation, do you?), I wonder if you haven''t taken the one with the most lightning in it as the best - was there something a touch simpler, and perhaps the more impactful for it? The sheer quantity here makes it perhaps less dramatic than a more coherent, simpler structure of lines might be.', '2006-09-20 17:30:09.000000', NULL, 1),
(2851745, 395693, 6999, '<td valign="top">Spark trails are always fun, but there are a couple of points I''d make about this shot; whilst you''ve done well in capturing the trails, you''re perhaps a bit under-exposed as far as the overall scene is concerned - a little extra light somewhere perhaps, give us more of an idea of context? And I''m unsure of your overall compositional sense here - the real centre of attention is the bright spot, but that seems slightly uncomfortably placed in frame to me, and without enough balancing interest in complementary areas. But it''s nicely done, despite those reservations.</td>', 'Spark trails are always fun, but there are a couple of points I''d make about this shot; whilst you''ve done well in capturing the trails, you''re perhaps a bit under-exposed as far as the overall scene is concerned - a little extra light somewhere perhaps, give us more of an idea of context? And I''m unsure of your overall compositional sense here - the real centre of attention is the bright spot, but that seems slightly uncomfortably placed in frame to me, and without enough balancing interest in complementary areas. But it''s nicely done, despite those reservations.', '2006-09-20 17:39:23.000000', NULL, 1),
(2851749, 398460, 43774, '<td valign="top">Love the colours and composition. There are lots of power lines in this challenge but this is one of the best.</td>', 'Love the colours and composition. There are lots of power lines in this challenge but this is one of the best.', '2006-09-20 17:40:33.000000', NULL, 1),
(2851752, 396916, 43774, '<td valign="top">Very cool, the best "plasma ball" shot in the challenge. I think I have to buy one of those! LOL</td>', 'Very cool, the best "plasma ball" shot in the challenge. I think I have to buy one of those! LOL', '2006-09-20 17:41:30.000000', NULL, 1),
(2851753, 398137, 43774, '<td valign="top">Pretty cool, nice and sharp, wish it were a little bit bigger.</td>', 'Pretty cool, nice and sharp, wish it were a little bit bigger.', '2006-09-20 17:41:56.000000', NULL, 1),
(2851754, 397501, 43774, '<td valign="top">Cute title, good composition!</td>', 'Cute title, good composition!', '2006-09-20 17:42:21.000000', NULL, 1),
(2851760, 397946, 56503, '<td valign="top">Very creative photo.  I myself would have never thought of a sparkplug.</td>', 'Very creative photo.  I myself would have never thought of a sparkplug.', '2006-09-20 17:43:32.000000', NULL, 1),
(2851768, 398622, 6999, '<td valign="top">For me this lacks any great impact; it''s composed to accentuate the sign - fair enough - but there''s no suprise there, nor visual parallel to the scene, just a quite straightforward and not very interesting warning. The fencing stops the strange structures of the sub-station making much impact in the image. I don''t really understand the point of it, I''m afraid.</td>', 'For me this lacks any great impact; it''s composed to accentuate the sign - fair enough - but there''s no suprise there, nor visual parallel to the scene, just a quite straightforward and not very interesting warning. The fencing stops the strange structures of the sub-station making much impact in the image. I don''t really understand the point of it, I''m afraid.', '2006-09-20 17:45:25.000000', NULL, 1),
(2851787, 398493, 6999, '<td valign="top">This verges on the feeling that there are two frames in one here - the regression of light in the road, and the cityscape alongside it seem almost completely disconnected - an intersting dynamic, though one senses that its more by chance here. A few things make it too complex an image for DPC - the strong vertical black thing, the slightly out of ordinary composition - the dynamic pulls us both to the top right and the bottom left where htat amber streetlight echoes the regression of others along the road - leaving the skyline and the other lighted window to almost simple clutter up the picture. It might work as a large print - but it pays never to forget that the medium you''re presenting in here is a really quite small web image - as a 2x1.4 inch print, would you expect this to work?</td>', 'This verges on the feeling that there are two frames in one here - the regression of light in the road, and the cityscape alongside it seem almost completely disconnected - an intersting dynamic, though one senses that its more by chance here. A few things make it too complex an image for DPC - the strong vertical black thing, the slightly out of ordinary composition - the dynamic pulls us both to the top right and the bottom left where htat amber streetlight echoes the regression of others along the road - leaving the skyline and the other lighted window to almost simple clutter up the picture. It might work as a large print - but it pays never to forget that the medium you''re presenting in here is a really quite small web image - as a 2x1.4 inch print, would you expect this to work?', '2006-09-20 17:51:59.000000', NULL, 1),
(2851796, 397940, 6999, '<td valign="top">Nice and neat, carefully balanced and processed - the black is properly black - and a strong compositional sense. A slightly bland subject choice for me - but this is a well executed approach to that.</td>', 'Nice and neat, carefully balanced and processed - the black is properly black - and a strong compositional sense. A slightly bland subject choice for me - but this is a well executed approach to that.', '2006-09-20 17:54:05.000000', NULL, 1),
(2851807, 397285, 6999, '<td valign="top">Interesting structures - but that isn''t enough by itself to make an impactful photograph. There''s no sense of scale here - these things could be five foot high, or fifty. Compositionally, you have two sets of lines working against each other - hte parallels of the background, and the diagonals of the power lines. The natural tendency is to follow converging lines to the vanishing point, but you''ve placed that out of frame, which leads the eye out of your image. The interest, I would say, is in the crazy shapes of those pylons, but your chosen point of view hasn''t made the most of that impact.</td>', 'Interesting structures - but that isn''t enough by itself to make an impactful photograph. There''s no sense of scale here - these things could be five foot high, or fifty. Compositionally, you have two sets of lines working against each other - hte parallels of the background, and the diagonals of the power lines. The natural tendency is to follow converging lines to the vanishing point, but you''ve placed that out of frame, which leads the eye out of your image. The interest, I would say, is in the crazy shapes of those pylons, but your chosen point of view hasn''t made the most of that impact.', '2006-09-20 18:01:20.000000', NULL, 1),
(2851829, 398122, 6999, '<td valign="top">More interesting than most. God knows why, but it has a certain south-american feeling to it - could just be the beat-up ceiling/wall, or the flies, or whetever they are. Maybe bare bulbs just always remind me of certain novels and films. Whatever. Kind of nice to be evocative with such a simple image.</td>', 'More interesting than most. God knows why, but it has a certain south-american feeling to it - could just be the beat-up ceiling/wall, or the flies, or whetever they are. Maybe bare bulbs just always remind me of certain novels and films. Whatever. Kind of nice to be evocative with such a simple image.', '2006-09-20 18:15:04.000000', NULL, 1),
(2851843, 398412, 6999, '<td valign="top">I like the steely-grey feel of the sky - has that kind of pre-storm greasy feeling. I don''t think you''ve served the strange geometry of the pylon particularly well with this point of view however: its arms might as well not be there, although nevertheless they''re present enough to know that they''ve not been shown to effect.</td>', 'I like the steely-grey feel of the sky - has that kind of pre-storm greasy feeling. I don''t think you''ve served the strange geometry of the pylon particularly well with this point of view however: its arms might as well not be there, although nevertheless they''re present enough to know that they''ve not been shown to effect.', '2006-09-20 18:22:48.000000', NULL, 1),
(2851844, 398458, 52449, '<td valign="top">I like the negative space off to the right--really well composed. However, a crop to make the faceplate level would have gained another point.</td>', 'I like the negative space off to the right--really well composed. However, a crop to make the faceplate level would have gained another point.', '2006-09-20 18:22:54.000000', NULL, 1),
(2851866, 397063, 65858, '<td valign="top">I think the thing here is that the subject fails to excite and engage the viewer.</td>', 'I think the thing here is that the subject fails to excite and engage the viewer.', '2006-09-20 18:33:28.000000', NULL, 1),
(2851871, 396172, 65858, '<td valign="top">I like the sharpness and reflections in the glass, and the twist on the common "lightbulb" theme.  The background isn''t perfectly black, and it''s a little distracting.</td>', 'I like the sharpness and reflections in the glass, and the twist on the common "lightbulb" theme.  The background isn''t perfectly black, and it''s a little distracting.', '2006-09-20 18:34:50.000000', NULL, 1),
(2851873, 398442, 6999, '<td valign="top">What a marvellously bizarre non-DPC photograph. After the usual string of attempts at shiny happy photography, this makes a refreshing change.</td>', 'What a marvellously bizarre non-DPC photograph. After the usual string of attempts at shiny happy photography, this makes a refreshing change.', '2006-09-20 18:35:05.000000', NULL, 1),
(2851876, 395793, 6999, '<td valign="top">Another one! Either you need serious monitor calibration, or I do.</td>', 'Another one! Either you need serious monitor calibration, or I do.', '2006-09-20 18:36:03.000000', NULL, 1),
(2851878, 398458, 65858, '<td valign="top">Decent shot, good placement.  I think the shortcoming is that the subject and presentation are somewhat unimaginative.</td>', 'Decent shot, good placement.  I think the shortcoming is that the subject and presentation are somewhat unimaginative.', '2006-09-20 18:36:54.000000', NULL, 1),
(2851883, 398381, 6999, '<td valign="top">Has a certain quality of 1950''s advertising photography - perhaps simple the idea that a hairdryer might be such a sought-after item, but I''d like to think its actually the tonality and composition. That''s no small compliment for a technical exercise - there were some great photographers working in advertising in the 1950s.</td>', 'Has a certain quality of 1950''s advertising photography - perhaps simple the idea that a hairdryer might be such a sought-after item, but I''d like to think its actually the tonality and composition. That''s no small compliment for a technical exercise - there were some great photographers working in advertising in the 1950s.', '2006-09-20 18:38:07.000000', NULL, 1),
(2851890, 397846, 65858, '<td valign="top">Interesting shot.  I like the blue glow.  I think a slightly tighter crop may have been more interesting.</td>', 'Interesting shot.  I like the blue glow.  I think a slightly tighter crop may have been more interesting.', '2006-09-20 18:39:59.000000', NULL, 1),
(2851892, 396916, 6999, '<td valign="top">Another one! Mind you, at least there''s no carefully lit human finger activating this.</td>', 'Another one! Mind you, at least there''s no carefully lit human finger activating this.', '2006-09-20 18:40:52.000000', NULL, 1),
(2851894, 397946, 65858, '<td valign="top">Interesting idea.  The graniness of the photo is a bit distracting.  A closer crop of the spark plug may also have been beneficial.</td>', 'Interesting idea.  The graniness of the photo is a bit distracting.  A closer crop of the spark plug may also have been beneficial.', '2006-09-20 18:41:25.000000', NULL, 1),
(2851907, 396387, 65858, '<td valign="top">I like how you took an ordinary object and portrayed it in an unordinary way: close-up, from an angle.  The shot looks sharp and has decent contrast, but I think the only problem is that it may be perceived as unimaginative.</td>', 'I like how you took an ordinary object and portrayed it in an unordinary way: close-up, from an angle.  The shot looks sharp and has decent contrast, but I think the only problem is that it may be perceived as unimaginative.', '2006-09-20 18:45:40.000000', NULL, 1),
(2851913, 395621, 65858, '<td valign="top">An interesting shot.  I know it would have blown out the sky, but I would have liked to see the building a bit lighter.  Perhaps some post processing of levels and contrast could have brought a better balance.</td>', 'An interesting shot.  I know it would have blown out the sky, but I would have liked to see the building a bit lighter.  Perhaps some post processing of levels and contrast could have brought a better balance.', '2006-09-20 18:47:15.000000', NULL, 1),
(2851919, 398389, 64446, '<td valign="top">Very cool...</td>', 'Very cool...', '2006-09-20 18:52:10.000000', NULL, 1),
(2851921, 396835, 64446, '<td valign="top">Nice sky and colors.</td>', 'Nice sky and colors.', '2006-09-20 18:52:24.000000', NULL, 1),
(2851922, 397810, 64446, '<td valign="top">Beautiful shot. I like the color transition you got here.<br/>Congratulations!</td>', 'Beautiful shot. I like the color transition you got here.Congratulations!', '2006-09-20 18:53:17.000000', NULL, 1),
(2851926, 397236, 64446, '<td valign="top">Very nice!</td>', 'Very nice!', '2006-09-20 18:53:46.000000', NULL, 1),
(2851932, 398071, 64446, '<td valign="top">Nice contrast with the birds and the subjects agains the bright blue.</td>', 'Nice contrast with the birds and the subjects agains the bright blue.', '2006-09-20 18:56:02.000000', NULL, 1),
(2851935, 398012, 48456, '<td valign="top">soo cool i love thunder!!! plus this looks like its going back up? peculiar...</td>', 'soo cool i love thunder!!! plus this looks like its going back up? peculiar...', '2006-09-20 18:56:31.000000', NULL, 1),
(2851938, 398441, 48456, '<td valign="top">i started psychotically cleaning my screen, but no, there is dust or something distracting in your photo, foreground... otherwise nice, a bit too white for candlelight</td>', 'i started psychotically cleaning my screen, but no, there is dust or something distracting in your photo, foreground... otherwise nice, a bit too white for candlelight', '2006-09-20 18:57:55.000000', NULL, 1),
