(2851970, 398460, 48456, '<td valign="top">the sepia works well here</td>', 'the sepia works well here', '2006-09-20 19:03:31.000000', NULL, 1),
(2851972, 395974, 6999, '<td valign="top">Interesting - arresting, and more so than many images in this challenge. Actually, I don''t get the connection to the challenge, whihch ought to be an issue, but I''m so bored of shots of those damn globe things that anything else seems like a balm, and then this also has social and political elements to it that just strike one immediately as ''proper'' photography. There''s a sense of some mad processing around the ewdges of the tree, but it remains one of the more interesting images I''ve seen today.</td>', 'Interesting - arresting, and more so than many images in this challenge. Actually, I don''t get the connection to the challenge, whihch ought to be an issue, but I''m so bored of shots of those damn globe things that anything else seems like a balm, and then this also has social and political elements to it that just strike one immediately as ''proper'' photography. There''s a sense of some mad processing around the ewdges of the tree, but it remains one of the more interesting images I''ve seen today.', '2006-09-20 19:04:17.000000', NULL, 1),
(2851978, 396645, 6999, '<td valign="top">Well, er, nicely lit I suppose.</td>', 'Well, er, nicely lit I suppose.', '2006-09-20 19:06:11.000000', NULL, 1),
