(2852756, 397017, 65107, '<td valign="top">the underbelly of electric lighting,  Its not pretty but its not completely lacking evocative power.  Its an intimidating light socket, better call an electrician</td>', 'the underbelly of electric lighting,  Its not pretty but its not completely lacking evocative power.  Its an intimidating light socket, better call an electrician', '2006-09-20 23:50:29.000000', NULL, 1),
(2852776, 397946, 65107, '<td valign="top">the spark of the plug that ignites the gas that drives piston that spins the wheel of civilization. The spark of life.  I like the metaphor, but I''m an engineer. I doubt most people will have no idea of what this is.</td>', 'the spark of the plug that ignites the gas that drives piston that spins the wheel of civilization. The spark of life.  I like the metaphor, but I''m an engineer. I doubt most people will have no idea of what this is.', '2006-09-20 23:59:27.000000', NULL, 1),
(2852782, 396510, 65107, '<td valign="top">Visually interesting but for me lacking an immediate connection with electricity</td>', 'Visually interesting but for me lacking an immediate connection with electricity', '2006-09-21 00:01:25.000000', NULL, 1),
(2852787, 398342, 65107, '<td valign="top">Why is it blue?</td>', 'Why is it blue?', '2006-09-21 00:02:33.000000', NULL, 1),
(2852837, 398378, 65107, '<td valign="top">This is a strong image.  Is it the ability of the light of a single lamp to isolate things.  Is that the effect of electricitry on society.</td>', 'This is a strong image.  Is it the ability of the light of a single lamp to isolate things.  Is that the effect of electricitry on society.', '2006-09-21 00:15:49.000000', NULL, 1),
(2852849, 397940, 64152, '<td valign="top">Wow!</td>', 'Wow!', '2006-09-21 00:19:08.000000', NULL, 1),
