(2852870, 398389, 65107, '<td valign="top">Nice image quality but I just don''t get it.</td>', 'Nice image quality but I just don''t get it.', '2006-09-21 00:28:04.000000', NULL, 1),
(2852873, 397287, 32581, '<td valign="top">cool one</td>', 'cool one', '2006-09-21 00:30:58.000000', NULL, 1),
(2852874, 398342, 32581, '<td valign="top">Cool one. Wish the filament was in sharp focus.</td>', 'Cool one. Wish the filament was in sharp focus.', '2006-09-21 00:32:00.000000', NULL, 1),
(2852881, 398412, 65107, '<td valign="top">Sometimes the lighting on a hazy day is really amazing.  The stark lines of the tower contrast nicely with the mystery of the mist.  But I don''t get the connection of electricity to the environment.  For example is the electrical tower ugly of beautiful?</td>', 'Sometimes the lighting on a hazy day is really amazing.  The stark lines of the tower contrast nicely with the mystery of the mist.  But I don''t get the connection of electricity to the environment.  For example is the electrical tower ugly of beautiful?', '2006-09-21 00:34:01.000000', NULL, 1),
(2852882, 398378, 32581, '<td valign="top">nice concept</td>', 'nice concept', '2006-09-21 00:34:10.000000', NULL, 1),
(2852883, 398012, 32581, '<td valign="top">nice capture.</td>', 'nice capture.', '2006-09-21 00:34:37.000000', NULL, 1),
(2852886, 397501, 32581, '<td valign="top">fantastic. I like the way the my eye navigates from the left bottom corner to the upper right corner. Good luck</td>', 'fantastic. I like the way the my eye navigates from the left bottom corner to the upper right corner. Good luck', '2006-09-21 00:37:25.000000', NULL, 1),
(2852890, 398016, 65107, '<td valign="top">infrastructure as art. On theme and well executed</td>', 'infrastructure as art. On theme and well executed', '2006-09-21 00:38:57.000000', NULL, 1),
(2852898, 398033, 65107, '<td valign="top">Lighting pictures are really cool bu don''t effectively address the effect of electricity of society and the environment.</td>', 'Lighting pictures are really cool bu don''t effectively address the effect of electricity of society and the environment.', '2006-09-21 00:41:22.000000', NULL, 1),
(2852909, 397805, 65107, '<td valign="top">Its and interesting image. I know its an electrical element, but it doesn''t comment on the broader theme of how electricity changes our lives.</td>', 'Its and interesting image. I know its an electrical element, but it doesn''t comment on the broader theme of how electricity changes our lives.', '2006-09-21 00:45:29.000000', NULL, 1),
(2852915, 398431, 65107, '<td valign="top">Tilting at windmills?  Personally I like windmills but this image makes it clear that windpower has its limitation.  To bad the windmills are not more clear.</td>', 'Tilting at windmills?  Personally I like windmills but this image makes it clear that windpower has its limitation.  To bad the windmills are not more clear.', '2006-09-21 00:48:37.000000', NULL, 1),
(2852925, 397813, 65107, '<td valign="top">The composition is too artistic to be called visual pollution.  I like the diagonal lines, they create an energy that conrasts with the smooth serenity of the sunrise ( sunset?)</td>', 'The composition is too artistic to be called visual pollution.  I like the diagonal lines, they create an energy that conrasts with the smooth serenity of the sunrise ( sunset?)', '2006-09-21 00:53:33.000000', NULL, 1),
(2852931, 398281, 65107, '<td valign="top">What''s it mean?  What is it?  A giant light bulb? Where is it?</td>', 'What''s it mean?  What is it?  A giant light bulb? Where is it?', '2006-09-21 00:56:13.000000', NULL, 1),
(2852940, 396645, 65107, '<td valign="top">So, is this considered degrading treatment under the Geneva Convention?  Did the electricity generate any useful intelligence?<br/> <br/>Seriously its a great image and directly related to the theme</td>', 'So, is this considered degrading treatment under the Geneva Convention?  Did the electricity generate any useful intelligence? Seriously its a great image and directly related to the theme', '2006-09-21 01:00:56.000000', NULL, 1),
(2852957, 398526, 65107, '<td valign="top">This image deserves a special category where there is obviously great skill and creativity in the setup and the photograph but it doesn''t quite live up to the caption</td>', 'This image deserves a special category where there is obviously great skill and creativity in the setup and the photograph but it doesn''t quite live up to the caption', '2006-09-21 01:10:18.000000', NULL, 1),
(2852965, 397802, 65107, '<td valign="top">You own the switch.  You decorated the switch. You are in control.<br/>I like this take on the theme.  Electrical energy domesticated.</td>', 'You own the switch.  You decorated the switch. You are in control.I like this take on the theme.  Electrical energy domesticated.', '2006-09-21 01:15:38.000000', NULL, 1),
(2852967, 398282, 65107, '<td valign="top">What is this place?</td>', 'What is this place?', '2006-09-21 01:17:04.000000', NULL, 1),
