(2852978, 398627, 65107, '<td valign="top">Pretty good technique.  Is that the wire behind the thumb.  Lack social/environmental comment</td>', 'Pretty good technique.  Is that the wire behind the thumb.  Lack social/environmental comment', '2006-09-21 01:24:28.000000', NULL, 1),
(2852989, 396836, 65107, '<td valign="top">Certainly electric trolleys transformed urban life.  The image is picture post card perfect but lack a value judgement and might benefit from a more human connection.</td>', 'Certainly electric trolleys transformed urban life.  The image is picture post card perfect but lack a value judgement and might benefit from a more human connection.', '2006-09-21 01:29:54.000000', NULL, 1),
