(2856898, 398060, 30049, '<td valign="top">This shouts electricity!  Well titled also.  The simple blue sky contrasts well with the pole and lines.  Good luck in the challenge.</td>', 'This shouts electricity!  Well titled also.  The simple blue sky contrasts well with the pole and lines.  Good luck in the challenge.', '2006-09-22 14:10:21.000000', NULL, 1),
(2856901, 397244, 28532, '<td valign="top">Very Nice!!  I really like the tones ~ your perspective is great on this shot - Excellent work!!</td>', 'Very Nice!!  I really like the tones ~ your perspective is great on this shot - Excellent work!!', '2006-09-22 14:14:17.000000', NULL, 1),
(2856905, 398526, 28532, '<td valign="top">Wow!!  Very cool!!  Just excellent all around!!</td>', 'Wow!!  Very cool!!  Just excellent all around!!', '2006-09-22 14:14:54.000000', NULL, 1),
(2856912, 395621, 28532, '<td valign="top">I really like the subdued feel to this ~ it''s kind of a contradiction to what it''s purpose is - makes you think a little.  Very Nice!</td>', 'I really like the subdued feel to this ~ it''s kind of a contradiction to what it''s purpose is - makes you think a little.  Very Nice!', '2006-09-22 14:18:08.000000', NULL, 1),
