(2856917, 398139, 28532, '<td valign="top">It has that early morning feel to it - Very well executed - Nice!!</td>', 'It has that early morning feel to it - Very well executed - Nice!!', '2006-09-22 14:20:29.000000', NULL, 1),
(2856919, 398460, 28532, '<td valign="top">Simple - yet complex at the same time - Great shot!!</td>', 'Simple - yet complex at the same time - Great shot!!', '2006-09-22 14:21:10.000000', NULL, 1),
