(2911831, 397810, 5885, '<td valign="top">Might be late, but congrats on the ribbon. Looks good on your profile :-)</td>', 'Might be late, but congrats on the ribbon. Looks good on your profile :-)', '2006-10-09 15:27:57.000000', NULL, 0),
(2911871, 397810, 31133, '<td valign="top">WHOOOOO!!! Look at you! Looks like Art Rotflmao was the first to congratulate you after all- he had good foresight. This is GREAT!!!! The ribbon looks perfect on you. Congratulations, Gugi!!</td>', 'WHOOOOO!!! Look at you! Looks like Art Rotflmao was the first to congratulate you after all- he had good foresight. This is GREAT!!!! The ribbon looks perfect on you. Congratulations, Gugi!!', '2006-10-09 15:42:47.000000', NULL, 0),
(2911935, 397810, 16241, '<td valign="top">congratulations!</td>', 'congratulations!', '2006-10-09 16:05:25.000000', NULL, 0),
(2911949, 397810, 57886, '<td valign="top">Jibbiiii... congrats on your ribbon :o)</td>', 'Jibbiiii... congrats on your ribbon :o)', '2006-10-09 16:09:58.000000', NULL, 0),
(2912193, 397810, 24454, '<td valign="top">Wow!  So sorry you had to wait so long to get the recognition you deserve for this award winning photo!  It''s amazing!   Congratulations!</td>', 'Wow!  So sorry you had to wait so long to get the recognition you deserve for this award winning photo!  It''s amazing!   Congratulations!', '2006-10-09 18:10:36.000000', NULL, 0),
