(2912444, 397810, 28742, '<td valign="top">Let me congratulate you (AGAIN) on the yellow ribbon! :D <br/>WAY overdue and very well deserved!</td>', 'Let me congratulate you (AGAIN) on the yellow ribbon! :D WAY overdue and very well deserved!', '2006-10-09 19:48:50.000000', NULL, 0),
(2914530, 397810, 52549, '<td valign="top">Hey, congrats on getting the yellow ribbon with this stunning image, I just read about it in the "Woody" thread in the forum.</td>', 'Hey, congrats on getting the yellow ribbon with this stunning image, I just read about it in the "Woody" thread in the forum.', '2006-10-10 15:47:28.000000', NULL, 0),
(2931433, 398378, 34938, '<td valign="top">This is a wonderful Australiana type image...love the feeling of the country at night that it evokes...the powerlines really round it off...well done</td>', 'This is a wonderful Australiana type image...love the feeling of the country at night that it evokes...the powerlines really round it off...well done', '2006-10-16 00:37:14.000000', NULL, 0),
(2941894, 397813, 42567, '<td valign="top">How did I miss this??  The colors look great!<br/> <br/>CONGRATULATIONS on your TOP 10!!!</td>', 'How did I miss this??  The colors look great! CONGRATULATIONS on your TOP 10!!!', '2006-10-18 21:11:51.000000', NULL, 0),
(2960883, 398554, 30982, '<td valign="top">Extremely well done and a very pleasing photograph to wander through!</td>', 'Extremely well done and a very pleasing photograph to wander through!', '2006-10-25 10:41:02.000000', NULL, 0),
(2996413, 398440, 30982, '<td valign="top">This is an excellent shot!  Wonderful composition and color, and the flying sparks really do add "spark" to the image.  Nicely done, great score, and nice finish, too!</td>', 'This is an excellent shot!  Wonderful composition and color, and the flying sparks really do add "spark" to the image.  Nicely done, great score, and nice finish, too!', '2006-11-03 23:02:17.000000', NULL, 0),
